const ABNORMAL_LINES_LAYER_ID = "events-lines-abnormal-layer";
const ALL_LINE_LAYER_IDS = [LINES_LAYER_ID, ABNORMAL_LINES_LAYER_ID];

const map = new maplibregl.Map({
  container: "map",
  style: {
    version: 8,
    sources: {
      osm: {
        type: "raster",
        tiles: [
          "https://a.tile.openstreetmap.org/{z}/{x}/{y}.png",
          "https://b.tile.openstreetmap.org/{z}/{x}/{y}.png",
          "https://c.tile.openstreetmap.org/{z}/{x}/{y}.png"
        ],
        tileSize: 256,
        attribution: "OpenStreetMap contributors"
      }
    },
    layers: [
      {
        id: "osm",
        type: "raster",
        source: "osm"
      }
    ]
  },
  center: [4.381970, 51.011861],
  zoom: 8
});

map.addControl(new maplibregl.NavigationControl({ visualizePitch: true }), "top-right");

const hoverChip = document.createElement("div");
hoverChip.className = "hover-chip";
document.body.appendChild(hoverChip);

function showHover(text, x, y) {
  hoverChip.textContent = text || "Unknown";
  hoverChip.style.left = `${x}px`;
  hoverChip.style.top = `${y}px`;
  hoverChip.style.display = "block";
}

function hideHover() {
  hoverChip.style.display = "none";
}

function escapeHtml(value) {
  return String(value ?? "N/A")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function popupHtml(properties, includeLength) {
  const items = [
    ["record_type", properties.record_type],
    ["start_time", properties.overall_start_time],
    ["end_time", properties.overall_end_time]
  ];

  if (includeLength) {
    const num = Number(properties.length);
    const lengthText = Number.isFinite(num) ? `${num.toFixed(2)} m` : "N/A";
    items.push(["length", lengthText]);
  }

  const rows = items.map(([key, value]) => (
    `<tr><th>${escapeHtml(key)}</th><td>${escapeHtml(value)}</td></tr>`
  )).join("");

  return `<table>${rows}</table>`;
}

function wireHover(layerId) {
  map.on("mousemove", layerId, (event) => {
    map.getCanvas().style.cursor = "pointer";
    const feature = event.features && event.features[0];
    if (!feature) {
      hideHover();
      return;
    }
    showHover(feature.properties.record_type, event.originalEvent.clientX, event.originalEvent.clientY);
  });

  map.on("mouseleave", layerId, () => {
    map.getCanvas().style.cursor = "";
    hideHover();
  });
}

function wireClicks() {
  map.on("click", POINTS_LAYER_ID, (event) => {
    const feature = event.features && event.features[0];
    if (!feature) {
      return;
    }

    new maplibregl.Popup({ closeButton: true, closeOnClick: true })
      .setLngLat(event.lngLat)
      .setHTML(popupHtml(feature.properties, false))
      .addTo(map);
  });

  ALL_LINE_LAYER_IDS.forEach((layerId) => {
    map.on("click", layerId, (event) => {
      const feature = event.features && event.features[0];
      if (!feature) {
        return;
      }

      new maplibregl.Popup({ closeButton: true, closeOnClick: true })
        .setLngLat(event.lngLat)
        .setHTML(popupHtml(feature.properties, true))
        .addTo(map);
    });
  });
}

function setLayerVisibility(layerId, isVisible) {
  if (!map.getLayer(layerId)) {
    return;
  }
  map.setLayoutProperty(layerId, "visibility", isVisible ? "visible" : "none");
}

async function loadGeoJson(url, fallbackData) {
  if (window.location.protocol === "file:") {
    return fallbackData;
  }
  try {
    const response = await fetch(url, { cache: "no-store" });
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }
    return await response.json();
  } catch (error) {
    console.warn(`Could not fetch ${url}; using embedded fallback data.`, error);
    return fallbackData;
  }
}

function extendBoundsFromCoords(bounds, coords) {
  if (!Array.isArray(coords) || coords.length === 0) {
    return;
  }
  if (typeof coords[0] === "number" && typeof coords[1] === "number") {
    bounds.extend([coords[0], coords[1]]);
    return;
  }
  coords.forEach((part) => extendBoundsFromCoords(bounds, part));
}

function fitToData(pointsData, linesData) {
  const bounds = new maplibregl.LngLatBounds();
  let count = 0;
  [pointsData, linesData].forEach((collection) => {
    const features = collection && Array.isArray(collection.features) ? collection.features : [];
    features.forEach((feature) => {
      const geometry = feature && feature.geometry;
      if (!geometry || !geometry.coordinates) {
        return;
      }
      extendBoundsFromCoords(bounds, geometry.coordinates);
      count += 1;
    });
  });
  if (count > 0) {
    map.fitBounds(bounds, { padding: 40, maxZoom: 13, duration: 0 });
  }
}

map.on("load", async () => {
  const pointsData = await loadGeoJson(POINTS_SOURCE_URL, INLINE_POINTS);
  const linesData = await loadGeoJson(LINES_SOURCE_URL, INLINE_LINES);

  map.addSource(POINTS_SOURCE_ID, {
    type: "geojson",
    data: pointsData
  });

  map.addSource(LINES_SOURCE_ID, {
    type: "geojson",
    data: linesData
  });

  map.addLayer({
    id: LINES_LAYER_ID,
    type: "line",
    source: LINES_SOURCE_ID,
    filter: ["!=", ["get", "record_type"], "AbnormalTraffic"],
    paint: {
      "line-color": "#255a92",
      "line-width": [
        "interpolate",
        ["linear"],
        ["zoom"],
        6, 2,
        10, 3,
        13, 5
      ],
      "line-opacity": 0.9
    }
  });

  map.addLayer({
    id: ABNORMAL_LINES_LAYER_ID,
    type: "line",
    source: LINES_SOURCE_ID,
    filter: ["==", ["get", "record_type"], "AbnormalTraffic"],
    paint: {
      "line-color": "#8e3dd1",
      "line-width": [
        "interpolate",
        ["linear"],
        ["zoom"],
        6, 3,
        10, 4.5,
        13, 7
      ],
      "line-opacity": 0.98
    }
  });

  map.addLayer({
    id: POINTS_LAYER_ID,
    type: "circle",
    source: POINTS_SOURCE_ID,
    paint: {
      "circle-color": [
        "match",
        ["get", "record_type"],
        "Accident", "#e53935",
        "AbnormalTraffic", "#8e3dd1",
        "#f39a2d"
      ],
      "circle-radius": [
        "interpolate",
        ["linear"],
        ["zoom"],
        6, 4,
        10, 6,
        13, 8
      ],
      "circle-stroke-color": "#ffffff",
      "circle-stroke-width": 1.25,
      "circle-opacity": 0.95
    }
  });

  wireHover(POINTS_LAYER_ID);
  ALL_LINE_LAYER_IDS.forEach((layerId) => wireHover(layerId));
  wireClicks();

  const pointsToggle = document.getElementById("toggle-points");
  const linesToggle = document.getElementById("toggle-lines");

  pointsToggle.addEventListener("change", () => {
    setLayerVisibility(POINTS_LAYER_ID, pointsToggle.checked);
  });
  linesToggle.addEventListener("change", () => {
    ALL_LINE_LAYER_IDS.forEach((layerId) => setLayerVisibility(layerId, linesToggle.checked));
  });

  fitToData(pointsData, linesData);
});
